head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[date > M > getMaxMinYear]<br/>config.xml 에 설정된 maxYear 와 minYear 값을 포함한 객체를 반환합니다.",
    "validation" : [
        "maxYear 와 minYear 속성을 포함한 객체를 반환해야 합니다.",
        "result.maxYear 는 config.xml 의 /WebSquare/date/maxYear/@value 에서 가져와야 합니다. 기본값은 2099 입니다.",
        "result.minYear 는 config.xml 의 /WebSquare/date/minYear/@value 에서 가져와야 합니다. 기본값은 1901 입니다.",
        // "maxYear 와 minYear 는 1000 ~ 9999 범위 내에서 유효하며, 범위를 벗어나거나 NaN 이면 기본값(maxYear=2099, minYear=1901)이 적용되어야 합니다.",
        // "minYear 가 maxYear 보다 큰 경우 두 값이 자동으로 교환되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getMaxMinYear_onclick = function () {
    let ret = WebSquare.date.getMaxMinYear();
    wf_body_bottom.getObj("scwin").setReturnValue("getMaxMinYear() : {maxYear: " + ret.maxYear + ", minYear: " + ret.minYear + "}");
}
